186	        String prefix = period.isEmpty() ? "X" : (String) period.get(0)[1];
187	        if (jdbc.update("UPDATE claim_sequence SET last_no = last_no + 1 WHERE sheet_id = ? AND seq_key = ?",
188	                sheetId, key) == 0) {
189	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, 1)", sheetId, key);
190	        }
191	        Long next = jdbc.queryForObject("SELECT last_no FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?",
192	                Long.class, sheetId, key);
193	        String number = prefix + "-" + next;
194	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
195	        kept(sheetId, claimId, true);
196	        return number;
197	    }
