230	    /** A claim's due now: its amount at the rate, in force on the claim's date, for the grade its person
231	     *  had on that date, falling back to the parent sheets' (see {@link #rateInForce})
232	     *  (the one with the latest from-date on or before it; an undated rate applies from the beginning
233	     *  of time; none applies when the claim's date is after that rate's to-date), rounded to two decimals by the claim's
234	     *  rounding (see {@link #rounding}) — the rate figure, not floored: the floor is applied last, in {@link #dueNow};
235	     *  null when no rate applies. */
236	    public BigDecimal due(String sheetId, Claim claim) {
237	        BigDecimal pct = rateInForce(sheetId, claim.personId(), LocalDate.parse(claim.date()));
238	        if (pct == null) return null;
239	        BigDecimal due = new BigDecimal(claim.amount()).multiply(pct).movePointLeft(2)
240	                .setScale(2, rounding(sheetId, claim));
241	        return due;
242	    }
