244	    /** How a claim's live figures round: half up when the claim is dated before the sheet's policy date
245	     *  (blank meaning the sheet's today), else half to even. A correction rounds by the date of the
246	     *  claim it corrects (its person's claim with that number), not its own. */
247	    public RoundingMode rounding(String sheetId, Claim claim) {
248	        String date = claim.date();
249	        if (claim.corrects() != null) {
250	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
251	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
252	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
253	        }
254	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
255	                Date.class, sheetId);
256	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
257	        return LocalDate.parse(date).isBefore(policy.get(0).toLocalDate()) ? RoundingMode.HALF_UP
258	                : RoundingMode.HALF_EVEN;
259	    }
