261	    /** A claim's figure now: the due fixed when it was settled, else the one its last statement bound
262	     *  it to (not while PENDING; none when it bound it to n/a), else its live rate figure (not floored); null when it has none. */
263	    public BigDecimal figure(String sheetId, Claim claim) {
264	        if (claim.due() != null) return new BigDecimal(claim.due());
265	        if (claim.bound() && claim.statedNa()) return null;
266	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
267	        return due(sheetId, claim);
268	    }
269	
270	    /** A claim's due now: a settled claim's frozen due; else the greater of the sheet's floor in force on the
271	     *  claim's date and its figure (the one its last statement bound it to, else its live rate figure) plus, while it
272	     *  is overdue (OPEN or PENDING and its due-by — fixed when it was created — plus its grade's grace days before the
273	     *  sheet's today), for every full 30 days it is overdue, the sheet's late percent in force on that boundary date (the
274	     *  due-by plus the grace plus 30, 60,
275	     *  90 ... days) of that figure plus the charges of the boundaries before it (compounding), each rounded to two decimals by the claim's rounding, the charges added up (a
276	     *  boundary whose percent is 0.00 adds nothing). A statement never binds the charge: it keeps following the
277	     *  sheet's today until settling freezes it in. A correction (a negative amount) has no floor and no late charge,
278	     *  nor does a deferred claim have a charge (it is not overdue). Null when it has no figure. */
279	    public BigDecimal dueNow(String sheetId, Claim claim) {
280	        if (claim.due() != null) return new BigDecimal(claim.due());
281	        BigDecimal figure = figure(sheetId, claim);
282	        if (figure == null || new BigDecimal(claim.amount()).signum() < 0) return figure;
283	        BigDecimal due = figure.add(lateCharge(sheetId, claim, figure));
284	        return due.max(settings.floor(sheetId, LocalDate.parse(claim.date())));
285	    }
