312	    /** The late charge on a claim's figure now (see {@link #dueNow}); zero when it is not overdue. */
313	    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure) {
314	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
315	        if (!claim.open() || claim.deferred()) return charge;
316	        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
317	        if (found.isEmpty()) return charge;
318	        LocalDate today = found.get(0).toLocalDate();
319	        LocalDate dueBy = overdueFrom(sheetId, claim);
320	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
321	        if (periods == 0) return charge;
322	        RoundingMode rounding = rounding(sheetId, claim);
323	        for (long n = 1; n <= periods; n++) {
324	            BigDecimal pct = settings.latePct(sheetId, dueBy.plusDays(30 * n));
325	            if (pct == null || pct.signum() == 0) continue;
326	            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
327	        }
328	        return charge;
329	    }
