354	        chain.add(sheetId);
355	        chain.addAll(settings.rateAncestors(sheetId));
356	        for (String at : chain) {
357	            List<BigDecimal> pct = jdbc.queryForList("SELECT a.pct FROM " + RATE_FOR + " a"
358	                    + " WHERE a.to_date IS NULL OR a.to_date >= CAST(? AS DATE)", BigDecimal.class,
359	                    at, grade.get(0), on.toString(), on.toString());
360	            if (!pct.isEmpty()) return pct.get(0);
361	        }
362	        return null;
363	    }
