398	    /** Move every claim of a person to another sheet, as the claims of the person {@code toPersonId} there: each keeps
399	     *  its status, dates, note, tags, settled due, status log, comments, lines and any figure a statement bound it to, and is listed
400	     *  in the same order; it loses its external reference, its lock and its settle batch. Each claim that had
401	     *  a number takes the other sheet's next one (as opening it there would give it), in the order the claims were
402	     *  opened (by the sheet's today when each was opened, then by the order they were added); a number one of them
403	     *  corrects or was split from follows it. The claims leave this sheet. */
404	    public void transferAll(String fromSheet, long personId, String toSheet, long toPersonId) {
405	        List<Long> ids = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
406	                Long.class, fromSheet, personId);
407	        Map<Long, Long> moved = new LinkedHashMap<>();
408	        for (Long claimId : ids) {
409	            GeneratedKeyHolder keys = new GeneratedKeyHolder();
410	            jdbc.update(c -> {
411	                PreparedStatement ps = c.prepareStatement("INSERT INTO claim (sheet_id, person_id, amount, claim_date, note,"
412	                        + " status, settled_due, opened_by, corrects, due_by, deferred_until, proofs, split_from, late_entry,"
413	                        + " reminded, tags, void_reason, edited_by, stated, stated_due, stated_na) SELECT ?, ?, amount, claim_date, note,"
414	                        + " status, settled_due, opened_by, corrects, due_by, deferred_until, proofs, split_from, late_entry,"
415	                        + " reminded, tags, void_reason, edited_by, stated, stated_due, stated_na FROM claim WHERE id = ? AND sheet_id = ?", new String[] { "id" });
416	                ps.setString(1, toSheet);
417	                ps.setLong(2, toPersonId);
418	                ps.setLong(3, claimId);
419	                ps.setString(4, fromSheet);
420	                return ps;
421	            }, keys);
422	            long arrived = keys.getKey().longValue();
423	            moved.put(claimId, arrived);
424	            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) SELECT ?, ?, status,"
425	                    + " by_user, on_date, due FROM claim_log WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
426	                    toSheet, arrived, fromSheet, claimId);
427	            jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, text) SELECT ?, ?, by_user,"
428	                    + " on_date, text FROM claim_comment WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
429	                    toSheet, arrived, fromSheet, claimId);
430	            jdbc.update("INSERT INTO claim_line (sheet_id, claim_id, label, qty, unit) SELECT ?, ?, label, qty, unit"
431	                    + " FROM claim_line WHERE sheet_id = ? AND claim_id = ? ORDER BY id", toSheet, arrived, fromSheet, claimId);
432	            used(toSheet, jdbc.queryForObject("SELECT tags FROM claim WHERE id = ?", String.class, arrived));
433	        }
434	
435	        // Renumber on the other sheet, in the order the claims were opened.
436	        List<Object[]> numbered = jdbc.query("SELECT c.id, c.claim_no, c.due_by FROM claim c WHERE c.sheet_id = ?"
437	                + " AND c.person_id = ? AND c.claim_no IS NOT NULL ORDER BY (SELECT MIN(l.on_date) FROM claim_log l"
438	                + " WHERE l.sheet_id = c.sheet_id AND l.claim_id = c.id AND l.status = 'OPEN') NULLS LAST, c.id",
439	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getString("claim_no"), rs.getDate("due_by").toLocalDate() },
440	                fromSheet, personId);
441	        boolean perPeriod = numbersPerPeriod(toSheet);
442	        Map<String, String> numbers = new LinkedHashMap<>();
443	        for (Object[] c : numbered) {
444	            long arrived = moved.get((Long) c[0]);
445	            numbers.put((String) c[1], perPeriod ? numberInPeriod(toSheet, arrived, (LocalDate) c[2]) : number(toSheet, arrived, (LocalDate) c[2]));
446	        }
447	        for (Long arrived : moved.values()) {
448	            Map<String, Object> was = jdbc.queryForMap("SELECT corrects, split_from FROM claim WHERE id = ?", arrived);
449	            String corrects = (String) was.get("corrects");
450	            String splitFrom = (String) was.get("split_from");
451	            jdbc.update("UPDATE claim SET corrects = ?, split_from = ? WHERE id = ?",
452	                    corrects == null ? null : numbers.getOrDefault(corrects, corrects),
453	                    splitFrom == null ? null : numbers.getOrDefault(splitFrom, splitFrom), arrived);
454	            history.claim(toSheet, arrived);
455	        }
456	
457	        for (Long claimId : ids) {
458	            jdbc.update("DELETE FROM claim_log WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
459	            jdbc.update("DELETE FROM claim_comment WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
460	            jdbc.update("DELETE FROM claim_line WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
461	            jdbc.update("DELETE FROM claim WHERE id = ? AND sheet_id = ?", claimId, fromSheet);
462	        }
463	    }
