530	    /** Re-fix, after a holiday is added to the sheet, the due-by of each claim not SETTLED or VOID whose due-by is on
531	     *  or after it: the terms-th business day after its date over the sheet's holidays now, for the terms it was fixed
532	     *  with (the business days from its date to its due-by over the holidays before, {@code before}). A claim whose
533	     *  due-by moves is kept in the history. */
534	    public void refixDueBy(String sheetId, java.util.Set<String> before, LocalDate holiday) {
535	        java.util.Set<String> now = new java.util.HashSet<>(before);
536	        now.add(holiday.toString());
537	        List<Object[]> open = jdbc.query("SELECT id, claim_date, due_by FROM claim WHERE sheet_id = ?"
538	                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ? ORDER BY id",
539	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getDate("claim_date").toLocalDate(),
540	                        rs.getDate("due_by").toLocalDate() }, sheetId, Date.valueOf(holiday));
541	        for (Object[] c : open) {
542	            LocalDate date = (LocalDate) c[1];
543	            LocalDate old = (LocalDate) c[2];
544	            LocalDate fixed = SettingsRepository.businessDaysAfter(now, date, businessDaysBetween(before, date, old));
545	            if (fixed.equals(old)) continue;
546	            jdbc.update("UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(fixed), c[0], sheetId);
547	            history.claim(sheetId, (Long) c[0]);
548	        }
549	    }
