551	    /** The business days (not a Saturday, Sunday or one of the holidays) after a date up to and including another. */
552	    private static int businessDaysBetween(java.util.Set<String> holidays, LocalDate from, LocalDate to) {
553	        int days = 0;
554	        for (LocalDate d = from.plusDays(1); !d.isAfter(to); d = d.plusDays(1)) {
555	            java.time.DayOfWeek day = d.getDayOfWeek();
556	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY && !holidays.contains(d.toString())) {
557	                days++;
558	            }
559	        }
560	        return days;
561	    }
