567	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects, String ref) {
568	        return add(sheetId, personId, amount, date, note, corrects, ref, null);
569	    }
570	
571	    /** Add a draft claim with an external reference (null: none) and tags (see {@link Claim#tags(String)}; null: none). */
572	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
573	        LocalDate dueBy = dueBy(sheetId, personId, date);
574	        boolean late = lateEntry(sheetId, dueBy);
575	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
576	        jdbc.update(c -> {
577	            PreparedStatement ps = c.prepareStatement(
578	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, late_entry, ref, tags) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
579	                    new String[] { "id" });
580	            ps.setString(1, sheetId);
581	            ps.setLong(2, personId);
582	            ps.setBigDecimal(3, amount);
583	            ps.setDate(4, Date.valueOf(date));
584	            ps.setString(5, note);
585	            ps.setString(6, corrects);
586	            ps.setDate(7, Date.valueOf(dueBy));
587	            ps.setBoolean(8, late);
588	            ps.setString(9, ref);
589	            ps.setString(10, tags);
590	            return ps;
591	        }, keys);
592	        kept(sheetId, keys.getKey().longValue(), true);
593	        used(sheetId, tags);
594	        return new Claim(keys.getKey().longValue(), personId, money(amount), date.toString(), note, "DRAFT", null, null, null, false, null, corrects,
595	                dueBy.toString(), false, null, false, 0, null, late, null, ref, tags, null);
596	    }
597	
598	    /** Whether a claim added now with a due-by is a late entry: the due-by falls in a soft-closed period of the sheet. */
599	    private boolean lateEntry(String sheetId, LocalDate date) {
600	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft_closed"
601	                + " AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
602	        return n != null && n > 0;
603	    }
604	
605	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from its last
606	     *  statement (live again); a new OPEN claim of the same person with the split-off amount, the same date and
607	     *  note and tags, opened by {@code by}, with its due-by fixed now and the original's number as split-from, is added
608	     *  (unnumbered: the caller numbers it; a late entry when its due-by falls in a soft-closed period). The new claim's id, or null when the sheet has no such OPEN claim. */
609	    public Long split(String sheetId, Claim claim, BigDecimal amount, String by) {
610	        BigDecimal rest = new BigDecimal(claim.amount()).subtract(amount);
611	        if (jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE"
612	                + " WHERE id = ? AND sheet_id = ? AND status = 'OPEN'", rest, claim.id(), sheetId) == 0) {
613	            return null;
614	        }
615	        kept(sheetId, claim.id(), true);
616	        LocalDate date = LocalDate.parse(claim.date());
617	        LocalDate dueBy = dueBy(sheetId, claim.personId(), date);
618	        boolean late = lateEntry(sheetId, dueBy);
619	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
620	        jdbc.update(c -> {
621	            PreparedStatement ps = c.prepareStatement(
622	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, due_by, status, opened_by, split_from, late_entry, tags)"
623	                            + " VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, ?, ?)",
624	                    new String[] { "id" });
625	            ps.setString(1, sheetId);
626	            ps.setLong(2, claim.personId());
627	            ps.setBigDecimal(3, amount);
628	            ps.setDate(4, Date.valueOf(date));
629	            ps.setString(5, claim.note());
630	            ps.setDate(6, Date.valueOf(dueBy));
631	            ps.setString(7, by);
632	            ps.setString(8, claim.number());
633	            ps.setBoolean(9, late);
634	            ps.setString(10, claim.tags());
635	            return ps;
636	        }, keys);
637	        kept(sheetId, keys.getKey().longValue(), true);
638	        return keys.getKey().longValue();
639	    }
640	
641	    /** Change a DRAFT claim's amount, date (with the due-by it now has), note, the number it corrects, its external reference (null: none) and
642	     *  its tags (null: none); false when the sheet has no such draft claim. */
643	    public boolean update(String sheetId, long claimId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note, String corrects, String ref,
644	            String tags) {
645	        boolean changed = kept(sheetId, claimId, jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, due_by = ?, note = ?, corrects = ?, ref = ?,"
646	                + " tags = ? WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
647	                amount, Date.valueOf(date), Date.valueOf(dueBy), note, corrects, ref, tags, claimId, sheetId) > 0);
648	        if (changed) used(sheetId, tags);
649	        return changed;
650	    }
651	
652	    /** Note tags (comma separated; null: none) as used on the sheet: each stays in {@link #tagsUsed} from now on. */
653	    private void used(String sheetId, String tags) {
654	        if (tags == null) return;
655	        for (String tag : tags.split(",")) {
656	            jdbc.update("MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", sheetId, tag);
657	        }
658	    }
659	
660	    /** Every tag ever used on the sheet, sorted. */
661	    public List<String> tagsUsed(String sheetId) {
662	        return jdbc.queryForList("SELECT tag FROM sheet_tag WHERE sheet_id = ? ORDER BY tag", String.class, sheetId);
663	    }
664	
665	    /** Whether an external reference is already used by a claim on the sheet other than {@code exceptId} (null: any),
666	     *  comparing without regard to case. */
667	    public boolean refUsed(String sheetId, String ref, Long exceptId) {
668	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND ref IS NOT NULL AND LOWER(ref) = LOWER(?)"
669	                + " AND id <> ?", Integer.class, sheetId, ref, exceptId == null ? -1L : exceptId);
670	        return n != null && n > 0;
671	    }
672	
673	    /** Lock a claim for {@code by}'s editor, releasing any other claim of the same person {@code by} held;
674	     *  false when another user holds the claim's lock. */
675	    public boolean lock(String sheetId, Claim claim, String by) {
676	        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE id = ? AND sheet_id = ?"
677	                + " AND (locked_by IS NULL OR locked_by = ?)", by, claim.id(), sheetId, by) == 0) {
678	            return false;
679	        }
680	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
681	                sheetId, claim.personId(), by, claim.id());
682	        return true;
683	    }
684	
685	    /** Release a claim's lock when {@code by} holds it. */
686	    public void unlock(String sheetId, long claimId, String by) {
687	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE id = ? AND sheet_id = ? AND locked_by = ?", claimId, sheetId, by);
688	    }
689	
690	    /** Release every claim lock on the sheet (its today changed). */
691	    public void unlockAll(String sheetId) {
692	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
693	    }
694	
695	    /** Who holds a claim's lock; null when it is not locked. */
696	    public String lockedBy(String sheetId, long claimId) {
697	        List<String> found = jdbc.queryForList("SELECT locked_by FROM claim WHERE id = ? AND sheet_id = ?", String.class,
698	                claimId, sheetId);
699	        return found.isEmpty() ? null : found.get(0);
700	    }
701	
702	    /** Make the sheet's next settle batch and give it to these claims: its number (1, 2, ... on the sheet). */
703	    public int batch(String sheetId, List<Long> claimIds) {
704	        jdbc.update("UPDATE sheet SET last_batch = COALESCE(last_batch, 0) + 1 WHERE id = ?", sheetId);
705	        int batch = lastBatch(sheetId);
706	        for (Long cid : claimIds) {
707	            jdbc.update("UPDATE claim SET batch = ? WHERE id = ? AND sheet_id = ?", batch, cid, sheetId);
708	        }
709	        return batch;
710	    }
711	
712	    /** The number of the sheet's last settle batch; null when there has been none. */
713	    public Integer lastBatch(String sheetId) {
714	        List<Integer> found = jdbc.queryForList("SELECT last_batch FROM sheet WHERE id = ?", Integer.class, sheetId);
715	        return found.isEmpty() ? null : found.get(0);
716	    }
717	
718	    /** The settle batch of each of the sheet's claims settled by one, by claim id. */
719	    public Map<String, Integer> batches(String sheetId) {
720	        Map<String, Integer> batches = new LinkedHashMap<>();
721	        jdbc.query("SELECT id, batch FROM claim WHERE sheet_id = ? AND batch IS NOT NULL",
722	                rs -> {
723	                    batches.put(String.valueOf(rs.getLong("id")), rs.getInt("batch"));
724	                }, sheetId);
725	        return batches;
726	    }
727	
728	    /** Who holds each locked claim of the sheet, by claim id. */
729	    public Map<String, String> locks(String sheetId) {
730	        Map<String, String> locks = new LinkedHashMap<>();
731	        jdbc.query("SELECT id, locked_by FROM claim WHERE sheet_id = ? AND locked_by IS NOT NULL",
732	                rs -> {
733	                    locks.put(String.valueOf(rs.getLong("id")), rs.getString("locked_by"));
734	                }, sheetId);
735	        return locks;
736	    }
737	
738	    /** Write a line of a claim's status log: its status now, who moved it there, the sheet's today and its
739	     *  due as computed now. */
740	    public void log(String sheetId, long claimId, String by) {
741	        Claim claim = find(sheetId, claimId);
742	        if (claim == null) return;
743	        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due)"
744	                + " SELECT ?, ?, ?, ?, today, ? FROM sheet WHERE id = ?",
745	                sheetId, claimId, claim.status(), by, dueNow(sheetId, claim), sheetId);
746	    }
747	
748	    /** How many days the sheet's today is past the date a claim's status log last records it SETTLED; null when
749	     *  it records no SETTLED line. */
750	    public Long daysSinceSettled(String sheetId, long claimId) {
751	        List<Long> found = jdbc.query("SELECT DATEDIFF('DAY', l.on_date, s.today) AS days FROM claim_log l"
752	                + " JOIN sheet s ON s.id = l.sheet_id WHERE l.sheet_id = ? AND l.claim_id = ? AND l.status = 'SETTLED'"
753	                + " ORDER BY l.id DESC LIMIT 1", (rs, i) -> rs.getLong("days"), sheetId, claimId);
754	        return found.isEmpty() ? null : found.get(0);
755	    }
756	
757	    /** Whether a claim's status log last records it DELETED on the sheet's today. */
758	    public boolean deletedToday(String sheetId, long claimId) {
759	        List<Long> found = jdbc.query("SELECT DATEDIFF('DAY', l.on_date, s.today) AS days FROM claim_log l"
760	                + " JOIN sheet s ON s.id = l.sheet_id WHERE l.sheet_id = ? AND l.claim_id = ? AND l.status = 'DELETED'"
761	                + " ORDER BY l.id DESC LIMIT 1", (rs, i) -> rs.getLong("days"), sheetId, claimId);
762	        return !found.isEmpty() && found.get(0) == 0;
763	    }
764	
765	    /** The status logs of the sheet's claims, by claim id: each a line per status it has had, oldest first,
766	     *  as "<STATUS> by <user> on <date> due=<due>" ('n/a' when it had no due). */
767	    public Map<String, List<String>> logs(String sheetId) {
768	        Map<String, List<String>> logs = new LinkedHashMap<>();
769	        jdbc.query("SELECT claim_id, status, by_user, on_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id",
770	                rs -> {
771	                    BigDecimal due = rs.getBigDecimal("due");
772	                    logs.computeIfAbsent(String.valueOf(rs.getLong("claim_id")), k -> new ArrayList<>())
773	                            .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
774	                                    + rs.getDate("on_date").toLocalDate() + " due=" + (due == null ? "n/a" : money(due)));
775	                }, sheetId);
776	        return logs;
777	    }
778	
779	    /** Keep a comment on a claim: its text, who wrote it and the sheet's today. */
780	    public void comment(String sheetId, long claimId, String by, String text) {
781	        jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, text)"
782	                + " SELECT ?, ?, ?, today, ? FROM sheet WHERE id = ?", sheetId, claimId, by, text, sheetId);
783	    }
784	
785	    /** The comments of the sheet's claims, by claim id: each oldest first, as "<user> on <date>: <text>". */
786	    public Map<String, List<String>> comments(String sheetId) {
787	        Map<String, List<String>> comments = new LinkedHashMap<>();
788	        jdbc.query("SELECT claim_id, by_user, on_date, text FROM claim_comment WHERE sheet_id = ? ORDER BY id",
789	                rs -> {
790	                    comments.computeIfAbsent(String.valueOf(rs.getLong("claim_id")), k -> new ArrayList<>())
791	                            .add(rs.getString("by_user") + " on " + rs.getDate("on_date").toLocalDate() + ": " + rs.getString("text"));
792	                }, sheetId);
793	        return comments;
794	    }
795	
796	    /** Add a line to a DRAFT claim and make its amount its lines' quantities times their unit amounts, added up: that
797	     *  amount, or null when the sheet has no such DRAFT claim (nothing is written then). */
798	    public BigDecimal addLine(String sheetId, long claimId, String label, int qty, BigDecimal unit) {
799	        Integer draft = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
800	                Integer.class, claimId, sheetId);
801	        if (draft == null || draft == 0) return null;
802	        jdbc.update("INSERT INTO claim_line (sheet_id, claim_id, label, qty, unit) VALUES (?, ?, ?, ?, ?)",
803	                sheetId, claimId, label, qty, unit);
804	        BigDecimal amount = linesTotal(sheetId, claimId);
805	        kept(sheetId, claimId, jdbc.update("UPDATE claim SET amount = ? WHERE id = ? AND sheet_id = ?", amount, claimId, sheetId) > 0);
806	        return amount;
807	    }
808	
809	    /** A claim's lines' quantities times their unit amounts, added up; null when it has no lines. */
810	    public BigDecimal linesTotal(String sheetId, long claimId) {
811	        List<BigDecimal> found = jdbc.queryForList("SELECT SUM(qty * unit) FROM claim_line WHERE sheet_id = ? AND claim_id = ?"
812	                + " HAVING COUNT(*) > 0", BigDecimal.class, sheetId, claimId);
813	        return found.isEmpty() || found.get(0) == null ? null : found.get(0).setScale(2);
814	    }
815	
816	    /** The lines of the sheet's claims, by claim id: each oldest first, as "<label> <qty> x <unit>". */
817	    public Map<String, List<String>> lines(String sheetId) {
818	        Map<String, List<String>> lines = new LinkedHashMap<>();
819	        jdbc.query("SELECT claim_id, label, qty, unit FROM claim_line WHERE sheet_id = ? ORDER BY id",
820	                rs -> {
821	                    lines.computeIfAbsent(String.valueOf(rs.getLong("claim_id")), k -> new ArrayList<>())
822	                            .add(rs.getString("label") + " " + rs.getInt("qty") + " x " + money(rs.getBigDecimal("unit")));
823	                }, sheetId);
824	        return lines;
825	    }
826	
827	    /** Each claim's status at the end of a day, by claim id, as its status log records it: the last line
828	     *  dated on or before it. A claim with no such line (added after that day) is absent. */
829	    public Map<Long, String> statusesOn(String sheetId, LocalDate day) {
830	        Map<Long, String> statuses = new LinkedHashMap<>();
831	        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
832	                rs -> {
833	                    statuses.put(rs.getLong("claim_id"), rs.getString("status"));
834	                }, sheetId, Date.valueOf(day));
835	        return statuses;
836	    }
837	
838	    /** An amount as shown: two decimals, a dot, no grouping. */
839	    static String money(BigDecimal amount) {
840	        return amount.setScale(2).toPlainString();
841	    }
842	
843	    /** A fixed due as shown, or null when there is none. */
844	    static String dueOf(BigDecimal due) {
845	        return due == null ? null : money(due);
846	    }
847	}
