171	        if (reversing) {
172	            tail = " reversed=" + (found.due() == null ? "n/a" : found.due());
173	        }
174	        if (voidReason != null) {
175	            tail += " reason=" + voidReason;
176	        }
177	        if (to.equals("SETTLED")) {
178	            BigDecimal now = repository.dueNow(id, found);
179	            repository.settleDue(id, cid, now);
180	            due = ClaimRepository.dueOf(now);
181	            tail = " due=" + (due == null ? "n/a" : due);
182	        }
183	        repository.log(id, cid, by);
184	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
185	                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
186	                found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(),
187	                voidReason != null ? voidReason : found.voidReason());
188	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
189	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
190	        // A settled (or approved) claim's watchers are told, after the claim's own line and before the rollup.
191	        if (event.equals("CLAIM_SETTLED") || event.equals("CLAIM_APPROVED")) {
192	            watches.notify(id, found.personId(), repository.personName(id, found.personId()), number, by, audit);
193	        }
194	        rollup.record(id, by, before);
195	        return changed;
196	    }
197	
198	    /** A steward re-settles a SETTLED claim (not in a closed period): its due is frozen again at the figure it would
199	     *  have today as an open claim bound by no statement (today's rates, grades, floor and late charge). */
200	    private static Claim resettle(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
201	            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
202	        Claim found = repository.find(id, cid);
203	        if (found == null) {
204	            throw new BadRequestException("no such claim");
205	        }
206	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
207	            throw new BadRequestException("only a steward can re-settle a claim");
208	        }
209	        if (!found.status().equals("SETTLED")) {
210	            throw new BadRequestException("only a SETTLED claim can be re-settled");
211	        }
212	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
213	        Claim live = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), "OPEN",
214	                found.number(), null, found.openedBy(), false, null, found.corrects(), found.dueBy(), false, null, false, found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason());
215	        BigDecimal now = repository.dueNow(id, live);
216	        Rollup.Snapshot before = rollup.take(id);
217	        repository.settleDue(id, cid, now);
218	        repository.log(id, cid, by);
219	        String old = found.due() == null ? "n/a" : found.due();
220	        String due = ClaimRepository.dueOf(now);
221	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(),
222	                found.status(), found.number(), due, found.openedBy(), found.stated(), found.statedDue(),
223	                found.corrects(), found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason());
224	        audit.record("CLAIM_RESETTLED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
225	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(found.number())
226	                + " old=" + old + " new=" + (due == null ? "n/a" : due));
227	        watches.notify(id, found.personId(), repository.personName(id, found.personId()), found.number(), by, audit);
228	        rollup.record(id, by, before);
229	        return changed;
230	    }
231	}
