347	        try {
348	            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
349	        } catch (NumberFormatException e) {
350	            throw new BadRequestException("no such claim");
351	        }
352	        Claim found = repository.find(id, cid);
353	        if (found == null) {
354	            throw new BadRequestException("no such claim");
355	        }
356	        // Only a draft can be edited: to change an open claim, void it and add a new one.
