368	        }
369	        LocalDate date = input.date() != null ? input.date() : sheets.today(id);
370	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
371	        people.claimAllowed(id, found.personId(), date);
372	        input.checkCorrection(repository, id, found.personId());
373	        input.checkRef(repository, id, cid);
374	        // A claim's due-by is fixed when it is created: editing its date leaves it as it is.
375	        String dueBy = found.dueBy();
376	        Rollup.Snapshot before = rollup.take(id);
377	        if (!repository.update(id, cid, input.amount(), date, LocalDate.parse(dueBy), input.note(), input.corrects(), input.ref(), input.tags())) {
