392	=== ClaimInput
393	
394	
395	/** A validated claim form: the amount (negative for a correction), the date ({@code null} when left blank:
396	 *  the sheet's today), the note, and the number of the claim a correction corrects ({@code null} when left blank), and its external reference (trimmed;
397	 *  {@code null} when left blank), and its tags (see {@link Claim#tags(String)}; {@code null} when none). */
398	public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
399	
400	    private static final Pattern SIGNED = Pattern.compile("-?(\\d+(\\.\\d{1,2})?|\\.\\d{1,2})");
401	
402	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?|\\.\\d{1,2}");
403	
404	    /** A typed amount (trimmed): required, a number with up to two decimals, 0.00 or more. */
405	    public static BigDecimal amount(String amount) throws BadRequestException {
406	        if (amount.isEmpty()) {
407	            throw new BadRequestException("amount is required");
408	        }
409	        if (!AMOUNT.matcher(amount).matches()) {
410	            throw new BadRequestException("amount must be a number of 0.00 or more with up to two decimals");
411	        }
412	        return new BigDecimal(amount).setScale(2);
413	    }
414	
415	    /** A typed claim-form amount (trimmed): required, a number with up to two decimals; a negative one
416	     *  is a correction. */
417	    public static BigDecimal signedAmount(String amount) throws BadRequestException {
418	        if (amount.isEmpty()) {
419	            throw new BadRequestException("amount is required");
420	        }
421	        if (!SIGNED.matcher(amount).matches()) {
422	            throw new BadRequestException("amount must be a number with up to two decimals");
423	        }
424	        return new BigDecimal(amount).setScale(2);
425	    }
426	
427	    /** Check the external reference against the sheet: one already used by another claim on it (other than
428	     *  {@code exceptId}, null: none), comparing without regard to case, is refused. */
429	    public void checkRef(ClaimRepository repository, String sheetId, Long exceptId) throws BadRequestException {
430	        if (ref != null && repository.refUsed(sheetId, ref, exceptId)) {
431	            throw new BadRequestException("reference " + ref + " is already used on the sheet");
432	        }
433	    }
434	
435	    /** Whether the amount is a correction's: below zero. */
436	    public boolean correction() {
437	        return amount.signum() < 0;
438	    }
439	
440	    /** Check the form against the person's claims: a negative amount must name, by number, a SETTLED
441	     *  claim of the same person; only a negative amount may name one. */
442	    public void checkCorrection(ClaimRepository repository, String sheetId, long personId) throws BadRequestException {
443	        if (!correction()) {
444	            if (corrects != null) {
445	                throw new BadRequestException("only a negative amount corrects a claim");
446	            }
447	            return;
448	        }
449	        if (corrects == null) {
450	            throw new BadRequestException("a negative amount is a correction: name the settled claim it corrects");
451	        }
452	        if (!repository.settledOf(sheetId, personId, corrects)) {
453	            throw new BadRequestException("claim " + corrects + " is not a settled claim of this person");
454	        }
455	    }
456	}
