460	/** Bind the claim form: an amount is required (a number with up to two decimals; a negative one is a
461	 *  correction), a blank date takes the sheet's entry date (its today when none is set), the note may be empty, and corrects is blank or
462	 *  the number of the claim a correction corrects, and the external reference is trimmed (blank: none), and the tags are kept as {@link Claim#tags(String)} has them. */
463	public class ValidateClaim {
464	    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> claim) throws BadRequestException {
465	        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
466	        String date = request == null || request.date() == null ? "" : request.date().trim();
467	        String note = request == null || request.note() == null ? "" : request.note().trim();
468	        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
