483	=== ClaimDelete
484	
485	
486	/** Delete a DRAFT claim (not in a closed period, nor held by another user's editor): it becomes DELETED, counts
487	 *  nowhere and can be neither edited, opened nor voided; its log gains a DELETED line and CLAIM_DELETED is written.
488	 *  Or restore a DELETED claim on the same sheet-today it was deleted: it is a DRAFT again, its log gains a DRAFT line
489	 *  and CLAIM_RESTORED is written; on a later day the restore is refused. Every check is made before anything is
490	 *  written, so a refusal writes nothing to the store or the audit. */
491	final class ClaimDelete {
492	    private ClaimDelete() {
493	    }
494	
495	    static Claim delete(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
496	            SettingsRepository settings, Audit audit) throws BadRequestException {
497	        if (settings.archived(id)) {
498	            throw new BadRequestException("the sheet is archived");
499	        }
500	        Claim found = repository.find(id, cid);
501	        if (found == null) {
502	            throw new BadRequestException("no such claim");
503	        }
504	        if (!found.status().equals("DRAFT")) {
505	            throw new BadRequestException("only a DRAFT claim can be deleted");
506	        }
507	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
508	        String holder = repository.lockedBy(id, cid);
509	        if (holder != null && !holder.equals(by)) {
510	            throw new BadRequestException("the claim is being edited by " + holder);
511	        }
512	        if (!repository.changeStatus(id, cid, List.of("DRAFT"), "DELETED")) {
513	            throw new BadRequestException("only a DRAFT claim can be deleted");
514	        }
515	        repository.unlock(id, cid, by);
516	        repository.log(id, cid, by);
517	        audit.record("CLAIM_DELETED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
518	                + " amount=" + found.amount() + " date=" + found.date());
519	        return repository.find(id, cid);
520	    }
521	
522	    static Claim restore(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
523	            SettingsRepository settings, Audit audit) throws BadRequestException {
524	        if (settings.archived(id)) {
525	            throw new BadRequestException("the sheet is archived");
526	        }
527	        Claim found = repository.find(id, cid);
528	        if (found == null) {
529	            throw new BadRequestException("no such claim");
530	        }
531	        if (!found.status().equals("DELETED")) {
532	            throw new BadRequestException("only a DELETED claim can be restored");
533	        }
534	        if (!repository.deletedToday(id, cid)) {
535	            throw new BadRequestException("a claim can be restored only on the day it was deleted");
536	        }
537	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
538	        if (!repository.changeStatus(id, cid, List.of("DELETED"), "DRAFT")) {
539	            throw new BadRequestException("only a DELETED claim can be restored");
540	        }
541	        repository.log(id, cid, by);
542	        audit.record("CLAIM_RESTORED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
543	                + " amount=" + found.amount() + " date=" + found.date());
544	        return repository.find(id, cid);
545	    }
546	}
547	=== ClaimReassign
548	
549	
550	/** A claim's move to another person, shared by the single and the bulk reassign: only a role the sheet's
551	 *  permission matrix allows (by default a steward) may; only a DRAFT, OPEN or PENDING claim, outside a closed
552	 *  period, and not to a person retired from before its date. The claim keeps its date and takes the next number in
553	 *  the sequence it would be numbered in now (the sheet's, or its period's), its old number never used again (a
554	 *  DRAFT, having none, gets none); it loses any figure a statement bound it to and is listed as its new person's
555	 *  newest claim. Every check is made before anything is written, so a refusal writes nothing to the store or the audit. */
556	final class ClaimReassign {
557	    private ClaimReassign() {
558	    }
559	
560	    /** @param ownAllowed whether a claim may be "moved" to the person it already is with (the bulk move
561	     *                    re-lists it as that person's newest); the single move refuses it */
562	    static Claim apply(String id, Long claimId, Long personId, boolean ownAllowed, String by, ClaimRepository repository,
563	            PeriodRepository periods, SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup)
564	            throws BadRequestException {
565	        if (claimId == null) {
566	            throw new BadRequestException("no such claim");
567	        }
568	        if (personId == null) {
569	            throw new BadRequestException("choose the person to move the claim to");
570	        }
571	        if (settings.archived(id)) {
572	            throw new BadRequestException("the sheet is archived");
573	        }
574	        if (!settings.allows(id, "reassign", by)) {
575	            throw new BadRequestException("a " + settings.role(id, by) + " cannot reassign a claim");
576	        }
577	        Claim found = repository.find(id, claimId);
578	        if (found == null) {
579	            throw new BadRequestException("no such claim");
580	        }
581	        if (!found.status().equals("DRAFT") && !found.open()) {
582	            throw new BadRequestException("a " + found.status() + " claim cannot be reassigned");
583	        }
584	        long to = personId;
585	        if (!repository.personExists(id, to)) {
586	            throw new BadRequestException("no such person");
587	        }
588	        if (to == found.personId() && !ownAllowed) {
589	            throw new BadRequestException("the claim is already that person's");
590	        }
591	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
592	        people.claimAllowed(id, to, LocalDate.parse(found.date()));
593	        String fromName = repository.personName(id, found.personId());
594	        String toName = repository.personName(id, to);
595	        Rollup.Snapshot before = rollup.take(id);
596	        if (!repository.reassign(id, found.id(), to)) {
597	            throw new BadRequestException("a " + found.status() + " claim cannot be reassigned");
598	        }
599	        String number = found.number();
600	        if (!found.status().equals("DRAFT")) {
601	            number = repository.numbersPerPeriod(id)
602	                    ? repository.numberInPeriod(id, found.id(), LocalDate.parse(found.dueBy()))
603	                    : repository.number(id, found.id(), LocalDate.parse(found.dueBy()));
604	        }
605	        Claim moved = new Claim(found.id(), to, found.amount(), found.date(), found.note(), found.status(),
606	                number, found.due(), found.openedBy(), false, null, found.corrects(), found.dueBy(), false,
607	                found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason());
608	        audit.record("CLAIM_REASSIGNED sheet=" + id + " by=" + by + " person=" + toName + " amount=" + moved.amount()
609	                + " date=" + moved.date() + Claim.auditNumber(moved.number()) + " from=" + fromName + " to=" + toName);
610	        rollup.record(id, by, before);
611	        return moved;
612	    }
613	}
