615	
616	
617	/** A steward re-dates an OPEN or PENDING claim: its due-by may not be in a closed period, nor the new date after its
618	 *  person's retirement. Its due-by stays as it was fixed and a figure its statement bound stays bound, so its period
619	 *  (the one containing its due-by) and its number stay as they are. Every check is made before anything is written,
620	 *  so a refusal writes nothing to the store or the audit. */
621	final class ClaimRedate {
622	    private ClaimRedate() {
623	    }
624	
625	    static Claim apply(String id, long cid, String newDate, String by, ClaimRepository repository,
626	            PeriodRepository periods, SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup)
627	            throws BadRequestException {
628	        if (settings.archived(id)) {
629	            throw new BadRequestException("the sheet is archived");
630	        }
631	        Claim found = repository.find(id, cid);
632	        if (found == null) {
633	            throw new BadRequestException("no such claim");
634	        }
635	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
636	            throw new BadRequestException("only a steward can re-date a claim");
637	        }
638	        if (!found.open()) {
639	            throw new BadRequestException("a " + found.status() + " claim cannot be re-dated");
640	        }
641	        String raw = newDate == null ? "" : newDate.trim();
642	        if (raw.isEmpty()) {
643	            throw new BadRequestException("give the claim's new date");
644	        }
645	        LocalDate date;
646	        try {
647	            date = LocalDate.parse(raw);
648	        } catch (DateTimeParseException e) {
649	            throw new BadRequestException("the new date must be yyyy-mm-dd");
650	        }
651	        LocalDate old = LocalDate.parse(found.date());
652	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
653	        people.claimAllowed(id, found.personId(), date);
654	        Rollup.Snapshot before = rollup.take(id);
655	        if (!repository.redate(id, cid, date)) {
656	            throw new BadRequestException("a " + found.status() + " claim cannot be re-dated");
657	        }
658	        String number = found.number();
659	        audit.record("CLAIM_REDATED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
660	                + " amount=" + found.amount() + " date=" + date + Claim.auditNumber(number)
661	                + " old=" + old + " new=" + date);
662	        rollup.record(id, by, before);
663	        return repository.find(id, cid);
664	    }
665	}
666	=== ClaimSplit
667	
668	
669	/** Split an amount (more than 0.00, less than the claim's amount) off an OPEN claim not deferred nor in a closed
670	 *  period (judged by the original claim's due-by alone), by a user whose role may open a claim: the claim keeps the rest and is unbound from its last statement;
671	 *  a new OPEN claim with the split-off amount, the same date and note and the next number, opened by the user, with
672	 *  its due-by fixed now and the original's number as split-from, is listed under the person. Every check is made
673	 *  before anything is written, so a refusal writes nothing to the store or the audit. Answers the new claim. */
674	final class ClaimSplit {
675	    private ClaimSplit() {
676	    }
677	
678	    static Claim apply(String id, long cid, String amount, String by, ClaimRepository repository,
679	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
680	        Claim found = repository.find(id, cid);
681	        if (found == null) {
682	            throw new BadRequestException("no such claim");
683	        }
684	        if (!found.status().equals("OPEN")) {
685	            throw new BadRequestException("a " + found.status() + " claim cannot be split");
686	        }
687	        if (found.deferred()) {
688	            throw new BadRequestException("a deferred claim cannot be split");
689	        }
690	        BigDecimal part = ClaimInput.amount(amount == null ? "" : amount.trim());
691	        if (part.signum() <= 0 || part.compareTo(new BigDecimal(found.amount())) >= 0) {
692	            throw new BadRequestException("the amount split off must be more than 0.00 and less than the claim's amount");
693	        }
694	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
695	        if (!settings.allows(id, "open", by)) {
696	            throw new BadRequestException("a " + settings.role(id, by) + " cannot open a claim, so cannot split one");
697	        }
698	        Rollup.Snapshot before = rollup.take(id);
699	        Long nid = repository.split(id, found, part, by);
700	        if (nid == null) {
701	            throw new BadRequestException("a " + found.status() + " claim cannot be split");
702	        }
703	        String number = repository.numbersPerPeriod(id)
704	                ? repository.numberInPeriod(id, nid, LocalDate.parse(repository.find(id, nid).dueBy()))
705	                : repository.number(id, nid, LocalDate.parse(repository.find(id, nid).dueBy()));
706	        repository.log(id, nid, by);
707	        Claim kept = repository.find(id, cid);
708	        Claim added = repository.find(id, nid);
709	        String person = repository.personName(id, found.personId());
710	        audit.record("CLAIM_SPLIT sheet=" + id + " by=" + by + " person=" + person + " amount=" + kept.amount()
711	                + " date=" + kept.date() + Claim.auditNumber(kept.number()) + " into=" + number);
712	        audit.record("CLAIM_OPENED sheet=" + id + " by=" + by + " person=" + person + " amount=" + added.amount()
713	                + " date=" + added.date() + Claim.auditNumber(number));
714	        rollup.record(id, by, before);
715	        return added;
716	    }
717	}
718	=== ClaimDeferral
719	
720	
721	/** Defer an OPEN claim (not in a closed period) until a date after the sheet's today: until the sheet's today
722	 *  reaches it, the claim counts in no total, is not overdue, cannot be settled and a statement leaves it
723	 *  unbound. Every check is made before anything is written, so a refusal writes nothing to the store or the audit. */
724	final class ClaimDeferral {
725	    private ClaimDeferral() {
726	    }
727	
728	    static Claim apply(String id, long cid, String until, String by, ClaimRepository repository, SheetRepository sheets,
729	            PeriodRepository periods, Audit audit, Rollup rollup) throws BadRequestException {
730	        Claim found = repository.find(id, cid);
731	        if (found == null) {
732	            throw new BadRequestException("no such claim");
733	        }
734	        if (!found.status().equals("OPEN")) {
735	            throw new BadRequestException("a " + found.status() + " claim cannot be deferred");
736	        }
737	        String raw = until == null ? "" : until.trim();
738	        if (raw.isEmpty()) {
739	            throw new BadRequestException("give the date to defer the claim until");
740	        }
741	        LocalDate date;
742	        try {
743	            date = LocalDate.parse(raw);
744	        } catch (DateTimeParseException e) {
745	            throw new BadRequestException("the date to defer until must be yyyy-mm-dd");
746	        }
747	        if (!date.isAfter(sheets.today(id))) {
748	            throw new BadRequestException("a claim can be deferred only to a date after today");
749	        }
750	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
751	        Rollup.Snapshot before = rollup.take(id);
752	        if (!repository.defer(id, cid, date)) {
753	            throw new BadRequestException("a " + found.status() + " claim cannot be deferred");
754	        }
755	        audit.record("CLAIM_DEFERRED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
756	                + " amount=" + found.amount() + " date=" + found.date() + Claim.auditNumber(found.number())
757	                + " until=" + date);
758	        rollup.record(id, by, before);
759	        return repository.find(id, cid);
760	    }
761	}
762	=== ClaimLock
763	
764	
765	/** A claim's editor lock: opening the editor (the edit button) locks the claim for every other user until its
766	 *  editor is saved or cancelled, or the sheet's today changes. Only a DRAFT outside a closed period can be
767	 *  edited: any other claim is refused and takes no lock, as is a claim another user holds. A refusal writes nothing. */
768	final class ClaimLock {
769	    private ClaimLock() {
770	    }
771	
772	    static Claim lock(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods)
773	            throws BadRequestException {
774	        Claim found = repository.find(id, cid);
775	        if (found == null) {
776	            throw new BadRequestException("no such claim");
777	        }
778	        if (!found.status().equals("DRAFT")) {
779	            throw new BadRequestException("only a DRAFT claim can be edited");
780	        }
781	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
782	        if (!repository.lock(id, found, by)) {
783	            throw new BadRequestException("the claim is being edited by " + repository.lockedBy(id, cid));
784	        }
785	        return found;
786	    }
787	
788	    static Claim unlock(String id, long cid, String by, ClaimRepository repository) throws BadRequestException {
789	        Claim found = repository.find(id, cid);
790	        if (found == null) {
791	            throw new BadRequestException("no such claim");
792	        }
793	        repository.unlock(id, cid, by);
794	        return found;
795	    }
796	}
797	=== ClaimProof
798	
799	
800	/** Raise a claim's proofs count by one: not a SETTLED, VOID or DELETED claim, nor one in a closed period. Every check is
801	 *  made before anything is written, so a refusal writes nothing to the store or the audit. */
802	final class ClaimProof {
803	    private ClaimProof() {
804	    }
805	
806	    static Claim apply(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
807	            Audit audit) throws BadRequestException {
808	        Claim found = repository.find(id, cid);
809	        if (found == null) {
810	            throw new BadRequestException("no such claim");
811	        }
812	        if (found.status().equals("SETTLED") || found.status().equals("VOID") || found.status().equals("DELETED")) {
813	            throw new BadRequestException("a " + found.status() + " claim cannot be given a proof");
814	        }
815	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
816	        Integer proofs = repository.addProof(id, cid);
817	        if (proofs == null) {
818	            throw new BadRequestException("a " + found.status() + " claim cannot be given a proof");
819	        }
820	        audit.record("CLAIM_PROOF_ADDED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
821	                + " amount=" + found.amount() + " date=" + found.date() + Claim.auditNumber(found.number())
822	                + " proofs=" + proofs);
823	        return repository.find(id, cid);
824	    }
825	}
826	=== ClaimRemind
827	
828	
829	/** Remind an OPEN or PENDING claim: its reminded date becomes the sheet's today, and REMIND is written. A claim can be
830	 *  reminded once per sheet-today; a second reminder that day, or one of a claim in any other status, is refused and
831	 *  writes nothing to the store or the audit. */
832	final class ClaimRemind {
833	    private ClaimRemind() {
834	    }
835	
836	    static Claim apply(String id, long cid, String by, ClaimRepository repository, Audit audit) throws BadRequestException {
837	        Claim found = repository.find(id, cid);
838	        if (found == null) {
839	            throw new BadRequestException("no such claim");
840	        }
841	        if (!found.open()) {
842	            throw new BadRequestException("a " + found.status() + " claim cannot be reminded");
843	        }
844	        if (!repository.remind(id, cid)) {
845	            throw new BadRequestException("the claim was already reminded today");
846	        }
847	        audit.record("REMIND sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
848	                + " amount=" + found.amount() + " date=" + found.date() + Claim.auditNumber(found.number()));
849	        return repository.find(id, cid);
850	    }
851	}
852	=== ClaimComment
853	
854	
855	/** Comment a claim: the text (trimmed) is kept with who wrote it and the sheet's today, and COMMENT_ADDED is
856	 *  written. An empty comment is refused and writes nothing to the store or the audit. */
857	final class ClaimComment {
858	    private ClaimComment() {
859	    }
860	
861	    static Claim apply(String id, long cid, String text, String by, ClaimRepository repository, Audit audit) throws BadRequestException {
862	        Claim found = repository.find(id, cid);
863	        if (found == null) {
864	            throw new BadRequestException("no such claim");
865	        }
866	        String trimmed = text == null ? "" : text.trim();
867	        if (trimmed.isEmpty()) {
868	            throw new BadRequestException("a comment cannot be empty");
869	        }
870	        repository.comment(id, cid, by, trimmed);
871	        audit.record("COMMENT_ADDED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
872	                + " amount=" + found.amount() + " date=" + found.date() + Claim.auditNumber(found.number()) + " text=" + trimmed);
873	        return found;
874	    }
875	}
876	=== ClaimLine
877	
878	
879	/** Add a line to a DRAFT claim: a label (trimmed, required), a quantity (a whole number, 1 or more) and a unit amount
880	 *  (up to two decimals, 0.00 or more). The claim's amount becomes its lines' quantities times their unit amounts,
881	 *  added up, and CLAIM_LINE_ADDED is written. Adding a line counts as editing the claim. A claim that is not a DRAFT,
882	 *  in a closed period, or locked by another user is refused; every check is made before anything is written, so a
883	 *  refusal writes nothing to the store or the audit. */
884	final class ClaimLine {
885	    private ClaimLine() {
886	    }
887	
888	    private static final Pattern QTY = Pattern.compile("\\d+");
889	
890	    static Claim apply(String id, long cid, String label, String qty, String unit, String by, ClaimRepository repository,
891	            PeriodRepository periods, SettingsRepository settings, Audit audit) throws BadRequestException {
892	        if (settings.archived(id)) {
893	            throw new BadRequestException("the sheet is archived");
894	        }
895	        Claim found = repository.find(id, cid);
896	        if (found == null) {
897	            throw new BadRequestException("no such claim");
898	        }
899	        if (!found.status().equals("DRAFT")) {
900	            throw new BadRequestException("only a DRAFT claim can be given a line");
901	        }
902	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
903	        String holder = repository.lockedBy(id, cid);
904	        if (holder != null && !holder.equals(by)) {
905	            throw new BadRequestException("the claim is being edited by " + holder);
906	        }
907	        String name = label == null ? "" : label.trim();
908	        if (name.isEmpty()) {
909	            throw new BadRequestException("a line needs a label");
910	        }
911	        String count = qty == null ? "" : qty.trim();
912	        if (!QTY.matcher(count).matches() || count.length() > 9 || Integer.parseInt(count) < 1) {
913	            throw new BadRequestException("a line's quantity must be a whole number of 1 or more");
914	        }
915	        int q = Integer.parseInt(count);
916	        BigDecimal u = ClaimInput.amount(unit == null ? "" : unit.trim());
917	        BigDecimal amount = repository.addLine(id, cid, name, q, u);
918	        if (amount == null) {
919	            throw new BadRequestException("only a DRAFT claim can be given a line");
920	        }
921	        repository.editedBy(id, cid, by);
922	        audit.record("CLAIM_LINE_ADDED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
923	                + " amount=" + ClaimRepository.money(amount) + " date=" + found.date() + Claim.auditNumber(found.number())
924	                + " label=" + name + " qty=" + q + " unit=" + ClaimRepository.money(u));
925	        return repository.find(id, cid);
926	    }
927	}
928	=== ReassignClaim
929	
930	
931	/** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, by the rules of {@link ClaimReassign};
932	 *  the claim's own person is refused. */
933	public class ReassignClaim {
934	    public void reassign(@PathVariable("sheetId") String sheetId, @RequestBody ReassignRequest request,
935	            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
936	            SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
937	        String by = CurrentUser.require(connection);
938	        String id = sheetId == null ? "" : sheetId.trim();
939	        if (request == null) {
940	            throw new BadRequestException("no such claim");
941	        }
942	        claim.set(ClaimReassign.apply(id, request.claimId(), request.personId(), false, by, repository, periods,
943	                settings, people, audit, rollup));
944	    }
945	}
