231	    /** Close, or soft-close, a period (open or soft-closed), fixing its figures afresh. A soft close writes
232	     *  PERIOD_SOFT_CLOSED instead of PERIOD_CLOSED. */
233	    public Period close(String sheetId, String by, Period found, boolean auto, boolean soft) {
234	        LocalDate from = LocalDate.parse(found.from());
235	        LocalDate to = LocalDate.parse(found.to());
236	        String today = periods.today(sheetId);
237	        Map<Long, List<Hold>> holds = new java.util.HashMap<>();
238	        BigDecimal total = BigDecimal.ZERO.setScale(2);
239	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
240	        for (Person p : people.list(sheetId)) {
241	            personTotals.put(p.id(), BigDecimal.ZERO.setScale(2));
242	            holds.put(p.id(), p.liveHolds(today));
243	        }
244	        Map<Long, String> statusesThen = claims.statusesOn(sheetId, to);
245	        for (Claim c : claims.list(sheetId)) {
246	            LocalDate on = LocalDate.parse(c.dueBy());
247	            if (on.isBefore(from) || on.isAfter(to)
248	                    || !c.countsAs(statusesThen.get(c.id()), holds.getOrDefault(c.personId(), List.of()), today)) continue;
249	            BigDecimal now = claims.dueNow(sheetId, c);
250	            if (now != null) {
251	                total = total.add(now);
252	                personTotals.merge(c.personId(), now, BigDecimal::add);
253	            }
254	        }
255	        String shown = total.setScale(2).toPlainString();
256	        periods.close(sheetId, found.id(), total, personTotals, soft);
257	        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + by + " period=" + found.name() + " total=" + shown
258	                + (auto ? " auto=yes" : ""));
259	        return new Period(found.id(), found.name(), found.from(), found.to(), !soft, shown, personTotals.entrySet().stream().collect(Collectors.toMap(e -> Long.toString(e.getKey()),
260	                e -> e.getValue().setScale(2).toPlainString(), (a, b) -> a, LinkedHashMap::new)), soft, found.cap());
261	    }
