263	    /** Close, by the sheet's grace days (none when blank), every open (not closed nor soft-closed) period whose to-date plus the grace days is
264	     *  before the sheet's today, in order of their to-dates. */
265	    public void closeLapsed(String sheetId, String by, LocalDate today) {
266	        Integer grace = settings.graceDays(sheetId);
267	        if (grace == null) return;
268	        List<Period> lapsed = periods.list(sheetId).stream()
269	                .filter(p -> !p.closed() && !p.softClosed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
270	                .sorted(Comparator.comparing(Period::to)).toList();
271	        for (Period p : lapsed) close(sheetId, by, p, true);
272	    }
