/** Move the selected claims to one person together, in list order (people in list order, each
 *  person's claims newest first), each by exactly the rules of moving one claim ({@link ClaimReassign}); a
 *  selected claim already that person's is re-listed as their newest. A claim that cannot be moved is left as
 *  it is and counted as refused. */
public class BulkReassignClaims {
    public void reassign(@PathVariable("sheetId") String sheetId, @RequestBody BulkReassignRequest request,
            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup,
            Out<BulkReassignResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Set<Long> selected = new LinkedHashSet<>();
        if (request != null && request.claimIds() != null) {
            for (Long cid : request.claimIds()) {
                if (cid != null) selected.add(cid);
            }
        }
        if (selected.isEmpty()) {
            throw new BadRequestException("select at least one claim");
        }
        if (request.personId() == null) {
            throw new BadRequestException("choose the person to move the claims to");
        }
        List<Claim> found = repository.inListOrder(id, selected);
        int refused = selected.size() - found.size();
        int reassigned = 0;
        for (Claim c : found) {
            try {
                ClaimReassign.apply(id, c.id(), request.personId(), true, by, repository, periods, settings, people, audit, rollup);
                reassigned++;
            } catch (BadRequestException e) {
                refused++;
            }
        }
        result.set(new BulkReassignResult(reassigned, refused));
    }
}


/** Re-date the selected claims together to one date, in list order (people in list order, each person's claims
 *  newest first), each by exactly the rules of re-dating one claim ({@link ClaimRedate}). A claim that cannot be
 *  re-dated is left as it is and counted as refused. */
public class BulkRedateClaims {
    public void redate(@PathVariable("sheetId") String sheetId, @RequestBody BulkRedateRequest request,
            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, PersonRepository people, Audit audit, Rollup rollup,
            Out<BulkRedateResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Set<Long> selected = new LinkedHashSet<>();
        if (request != null && request.claimIds() != null) {
            for (Long cid : request.claimIds()) {
                if (cid != null) selected.add(cid);
            }
        }
        if (selected.isEmpty()) {
            throw new BadRequestException("select at least one claim");
        }
        List<Claim> found = repository.inListOrder(id, selected);
        int refused = selected.size() - found.size();
        int redated = 0;
        for (Claim c : found) {
            try {
                ClaimRedate.apply(id, c.id(), request.date(), by, repository, periods, settings, people, audit, rollup);
                redated++;
            } catch (BadRequestException e) {
                refused++;
            }
        }
        result.set(new BulkRedateResult(redated, refused));
    }
}


/** Settle the selected claims together, all or nothing: when any of them cannot be settled by the signed-in
 *  user (any refusal the single settle would give; going to PENDING is not one), none is settled, every one
 *  counts as refused and nothing is written. Otherwise each is settled in list order (people in list order
 *  were added, each person's claims newest first) by exactly the rules of settling one claim (a claim a clerk
 *  sends to PENDING counts as settled); they are the sheet's next batch, each keeps its number, and after the
 *  claims' own lines BATCH_SETTLED batch=<n> count=<claims> total=<the frozen dues of those SETTLED> is written. */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @RequestBody BulkSettleRequest request,
            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches, Out<BulkSettleResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Set<Long> selected = new LinkedHashSet<>();
        if (request != null && request.claimIds() != null) {
            for (Long cid : request.claimIds()) {
                if (cid != null) selected.add(cid);
            }
        }
        if (selected.isEmpty()) {
            throw new BadRequestException("select at least one claim");
        }
        List<Claim> found = repository.inListOrder(id, selected);
        boolean refusedAny = found.size() < selected.size();
        for (Claim c : found) {
            if (refusedAny) break;
            try {
                ClaimStatusChange.check(id, c.id(), "settle", by, repository, periods, settings);
            } catch (BadRequestException e) {
                refusedAny = true;
            }
        }
        if (refusedAny) {
            result.set(new BulkSettleResult(0, selected.size()));
            return;
        }
        List<Long> settled = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : found) {
            Claim changed = ClaimStatusChange.apply(id, c.id(), "settle", by, repository, periods, settings, audit, rollup, watches);
            settled.add(c.id());
            if ("SETTLED".equals(changed.status()) && changed.due() != null) {
                total = total.add(new BigDecimal(changed.due()));
            }
        }
        int batch = repository.batch(id, settled);
        audit.record("BATCH_SETTLED sheet=" + id + " by=" + by + " batch=" + batch + " count=" + settled.size()
                + " total=" + total.toPlainString());
        result.set(new BulkSettleResult(settled.size(), 0));
    }
}
