635	 *  its from-date), their terms, contact and aliases, and their claims (see {@link ClaimRepository#transferAll}), with
636	 *  their statements (see {@link PersonRepository#joinStatements}); they leave this sheet entirely (patron links, pool memberships, holds and watches dropped).
637	 *  A sheet id never used is made empty first, as loading it would. Refused for anyone but a steward, for a retired
638	 *  person, for this sheet's own id, and for an archived sheet. When their name or an alias is already a name or alias
639	 *  of someone on the other sheet, they are merged into that person there, as {@link MergePerson} does (claims after
640	 *  theirs, aliases joined, bound figures kept, statements joined; refused when that person is retired or more than one person matches);
641	 *  otherwise refused when their name, an alias or their contact is already taken there. Each sheet writes its
642	 *  PERSON_TRANSFERRED line (the other sheet then PERSON_MERGED when merged), then its rollup lines. */
643	public class TransferPerson {
644	    public void transfer(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
645	            @RequestBody TransferRequest request, ServerHttpConnection connection, PersonRepository people,
646	            AliasRepository aliases, ClaimRepository claims, SettingsRepository settings, SheetRepository sheets, Audit audit,
647	            Rollup rollup,
648	            Out<Person> person) throws BadRequestException {
649	        String by = CurrentUser.require(connection);
650	        String id = sheetId == null ? "" : sheetId.trim();
651	        long pid;
652	        try {
653	            pid = Long.parseLong(personId == null ? "" : personId.trim());
654	        } catch (NumberFormatException e) {
655	            throw new BadRequestException("no such person");
656	        }
657	        Person from = people.find(id, pid);
658	        if (from == null) {
659	            throw new BadRequestException("no such person");
660	        }
661	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
662	            throw new BadRequestException("only a steward can transfer people");
663	        }
664	        if (from.retired()) {
665	            throw new BadRequestException(from.name() + " is retired");
666	        }
667	        String to = request == null || request.toSheetId() == null ? "" : request.toSheetId().trim();
668	        if (to.isEmpty()) {
669	            throw new BadRequestException("enter the sheet to transfer to");
670	        }
671	        if (to.equals(id)) {
672	            throw new BadRequestException("a person cannot be transferred to their own sheet");
673	        }
674	        if (settings.archived(to)) {
675	            throw new BadRequestException("sheet " + to + " is archived");
676	        }
677	        List<String> names = new ArrayList<>(List.of(from.name()));
678	        for (Alias alias : aliases.list(id)) {
679	            if (alias.personId() == pid) names.add(alias.alias());
680	        }
681	        Person into = null;
682	        for (String name : names) {
683	            Person match = people.findByName(to, name);
684	            if (match == null) continue;
685	            if (into != null && into.id() != match.id()) {
686	                throw new BadRequestException(name + " is already on sheet " + to);
687	            }
688	            into = match;
689	        }
690	        if (into != null) {
691	            if (into.retired()) {
692	                throw new BadRequestException(into.name() + " is retired");
693	            }
694	        } else {
695	            for (String name : names) {
696	                if (people.nameTaken(to, name, pid)) {
697	                    throw new BadRequestException(name + " is already on sheet " + to);
698	                }
699	            }
700	            if (from.contact() != null && people.contactTaken(to, from.contact(), 0)) {
701	                throw new BadRequestException(from.contact() + " is already on sheet " + to);
702	            }
703	        }
704	
705	        if (!people.sheetExists(to)) {
706	            sheets.loadOrCreate(to, by);
707	        }
708	        Rollup.Snapshot beforeHere = rollup.take(id);
709	        Rollup.Snapshot beforeThere = rollup.take(to);
710	        long arrived;
711	        if (into == null) {
712	            arrived = people.transferIn(id, pid, to);
713	            claims.transferAll(id, pid, to, arrived);
714	        } else {
715	            // They arrive as merged into the person already there: their claims after that person's, their name
716	            // and aliases joined to that person's aliases.
717	            arrived = into.id();
718	            claims.transferAll(id, pid, to, arrived);
719	            people.joinAliases(to, arrived, names);
720	        }
721	        people.joinStatements(id, pid, to, arrived);
722	        people.remove(id, pid);
723	        audit.record("PERSON_TRANSFERRED sheet=" + id + " by=" + by + " name=" + from.name() + " to=" + to);
724	        rollup.record(id, by, beforeHere);
725	        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + by + " name=" + from.name() + " from=" + id);
726	        if (into != null) {
727	            audit.record("PERSON_MERGED sheet=" + to + " by=" + by + " from=" + from.name() + " into=" + into.name());
728	        }
729	        rollup.record(to, by, beforeThere);
730	        person.set(people.find(to, arrived));
731	    }
732	}
