=== statement/TakeStatement


/** Take a person's statement: record their due-total now, and bind each claim of theirs that counts (a
 *  person's open (OPEN or PENDING) claims dated within a hold do not, unless already bound) to the figure it has now — its rate figure, not floored (a settled claim keeps its frozen due); a
 *  claim with no figure because the rate that would apply to it has ended is bound to n/a; a
 *  claim that does not count is unbound (live again). A late charge is never bound, nor is the floor: they keep following
 *  the sheet's today. The due-total is as shown: the sum of the counting claims' dues now (late charges
 *  included), skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today
 *  is in force then and no counting claim has a fixed figure or a due (at the grade it was claimed under); at
 *  most the sheet's cap.
 *
 *  <p>Taken as of a date (on or before the sheet's today; a later one is refused, as is one before the person
 *  was added), it binds the claims of theirs that counted at the end of that date to their figures as they
 *  stood then: every change made while the sheet's today was on or before that date counts, every later one
 *  does not, and that date stands in for the sheet's today in every figure (see {@link SheetAsOf}). Every
 *  other claim of theirs is unbound. The statement's date is that date, its due-total that day's, and its
 *  record ends with asof=<date>. */
public class TakeStatement {
    public void take(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val StatementInput input, ServerHttpConnection connection, PersonRepository people, ClaimRepository claims,
            SheetRepository sheets, SettingsRepository settings, HistoryRepository history, Audit audit, Rollup rollup,
            Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = people.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        LocalDate today = sheets.today(id);
        LocalDate asof = input.asof();
        if (asof != null) {
            if (today != null && asof.isAfter(today)) {
                throw new BadRequestException("a statement cannot be taken as of a date after the sheet's today (" + today + ")");
            }
            if (!history.existed(id, pid, asof)) {
                throw new BadRequestException(found.name() + " was not on the sheet on " + asof);
            }
        }
        SheetAsOf then = asof == null ? null : history.asOf(id, asof);
        List<Hold> holds = then == null ? found.liveHolds(today == null ? null : today.toString()) : then.liveHolds(pid);
        Rollup.Snapshot before = rollup.take(id);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int count = 0;
        for (Claim live : claims.ofPerson(id, pid)) {
            // As of a date, the claim as it stood then: absent when it was added later, or was another's then.
            Claim c = then == null ? live : then.claims().get(live.id());
            if (c == null || c.personId() != pid || !c.counts(holds)) {
                claims.bind(id, live.id(), false, null, false);
                continue;
            }
            count++;
            fixed |= c.fixed();
            // The claim is bound to its figure; its late charge is not bound, but counts in the due-total.
            BigDecimal figure = then == null ? claims.figure(id, c) : then.figure(c);
            BigDecimal now = then == null ? claims.dueNow(id, c) : then.dueNow(c);
            if (now != null) {
                total = total.add(now);
                fixed = true;
            }
            // With no figure (no rate applies, or it is bound to n/a already) it is bound to n/a: it stays
            // n/a even once a rate is in force on its date (a later rate, or a new grade for its person then).
            boolean na = figure == null;
            claims.bind(id, c.id(), true, figure, na);
        }
        boolean rated = then == null ? claims.rated(id, pid, today) : then.rated(pid);
        BigDecimal cap = then == null ? settings.cap(id) : then.cap();
        String dueTotal = fixed || rated ? SettingsRepository.capped(total, cap).setScale(2).toPlainString() : "n/a";
        people.stated(id, pid, dueTotal, asof == null ? today : asof);
        audit.record("STATEMENT sheet=" + id + " by=" + by + " name=" + found.name() + " due-total=" + dueTotal
                + " claims=" + count + (asof == null ? "" : " asof=" + asof));
        rollup.record(id, by, before);
        person.set(people.find(id, pid));
    }
}
=== statement/CancelStatement


/** A steward cancels a person's last statement: the claims it bound are unbound (live again — a figure a
 *  statement before it bound is not restored), the statement count goes down by one, and the person shows
 *  the due-total and date of the statement before it (or nothing). Refused for anyone but a steward, and
 *  for a person with no statement. */
public class CancelStatement {
    public void cancel(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims,
            SettingsRepository settings, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = people.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can cancel a statement");
        }
        if (found.statementCount() <= 0) {
            throw new BadRequestException(found.name() + " has no statement to cancel");
        }
        Rollup.Snapshot before = rollup.take(id);
        for (Claim c : claims.ofPerson(id, pid)) {
            claims.bind(id, c.id(), false, null, false);
        }
        people.unstated(id, pid);
        audit.record("STATEMENT_CANCELLED sheet=" + id + " by=" + by + " name=" + found.name()
                + " due-total=" + found.statedTotal());
        rollup.record(id, by, before);
        person.set(people.find(id, pid));
    }
}
=== settings/Settings


/** A sheet's settings: its clerk limit (two decimals; null means no limit), its floor (two decimals:
 *  the least a live due can be), its terms (the business days after a claim's date that it is due by), its late percent (two decimals: what an
 *  overdue claim's due gains, of its figure, for every full 30 days it is overdue), the roles set on it, by user name. A name not listed is a clerk. And its policy date (yyyy-MM-dd; null when blank,
 *  meaning the sheet's today): a claim dated before it rounds half up, one on or after it half to even. And its period numbering from-date (yyyy-MM-dd; null when blank, meaning off):
 *  while set and the sheet's today is on or after it, a claim opened is numbered within its period. And each grade's own terms,
 *  by grade (a grade not listed uses the sheet's terms). And its cap (two decimals; null means none): a
 *  person's due-total is at most it. The clerk limit, floor, terms, late percent, grade terms and cap are those in
 *  force on the sheet's today; {@code dated} is every value recorded for each of them, by key (clerk-limit, floor,
 *  terms, terms-<grade>, late-pct, cap, proof-threshold, proof-threshold-<grade>), oldest from-date first. {@code permissions} is the permission
 *  matrix entries set, by action (open, settle, void, reassign, close, reopen), each a comma separated list of roles; an
 *  action not listed keeps the standing rule. {@code graceDays} is the days after a period's to-date it is left
 *  open (null when blank: off; not dated): changing the sheet's today closes each open period lapsed past them.
 *  {@code delegations} is each delegation of the steward role made on the sheet, oldest first.
 *  {@code entryDate} is the sheet's entry date (yyyy-MM-dd; null when blank: off; not dated): while set, it is the
 *  default date of a new claim instead of the sheet's today. {@code holidays} is the sheet's holidays (yyyy-MM-dd),
 *  earliest first: a claim's due-by, fixed when it is created, that falls on one is moved to the next day that is not one.
 *  {@code voidReasons} is the sheet's void reasons, in the order they were added: while there is one, voiding a claim
 *  needs one of them. {@code pot} is the sheet's pot (two decimals; null when blank: none; not dated): each member of
 *  a balanced pool gets a cut of it. {@code parent} is the sheet's parent sheet id (null when blank: none; not dated):
 *  a grade with no rate in force on a date takes the parent's, then its parent's, up to three levels up.
 *  {@code fiscalStartMonth} is the month (1 to 12; 1 unless set; not dated) the sheet's fiscal year starts in: a fiscal
 *  year is named FY<yyyy> by the calendar year its first day falls in.
 *  {@code alertThreshold} is the sheet's alert threshold (two decimals; null when blank: off; not dated): a person
 *  whose due-total goes from at or below it to above it is written an ALERT line. */
public record Settings(String clerkLimit, String floor, int terms, String latePct, List<Role> roles, String policyDate,
        String periodNumberingFrom, java.util.Map<String, Integer> gradeTerms, String cap,
        java.util.Map<String, List<DatedValue>> dated, java.util.Map<String, String> permissions, Integer graceDays,
        List<Delegation> delegations, String entryDate, List<String> holidays, List<String> voidReasons,
        String pot, String parent, int fiscalStartMonth, String alertThreshold) {
}
=== sheet/SaveSheetToday


/** Set the sheet's today (a new date first records each person's due-total as it stood on the day left, and releases every claim's editor lock), then close each open period lapsed past the sheet's grace days. */
public class SaveSheetToday {
    public void save(@PathVariable("sheetId") String sheetId, @Val LocalDate today,
            ServerHttpConnection connection, SheetRepository repository, Rollup rollup, PeriodCloser closer, ClaimRepository claims,
            SettingsRepository settings,
            Out<Sheet> sheet)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Rollup.Snapshot before = rollup.take(id);
        // A change of today under a delegation is marked for its steward as the delegation stood on the day left.
        String delegator = settings.delegator(id, by);
        LocalDate was = repository.today(id);
        if (!repository.setToday(id, today)) {
            throw new BadRequestException("no such sheet");
        }
        if (!today.equals(was)) {
            rollup.snapshot(id, by, before, delegator, was);
            claims.unlockAll(id);
        }
        closer.closeLapsed(id, by, today);
        rollup.record(id, by, before);
        sheet.set(new Sheet(id, today.toString(), repository.archived(id)));
    }
}
