/** Bind the plan form: an amount (more than zero, up to two decimals), a start date, every N days (a whole number,
 *  at least 1) or a day of the month (1 to 31), not both, and an end date not before the start are all required. */
public class ValidatePlan {
    public void validate(@RequestBody PlanRequest request, Out<PlanInput> plan) throws BadRequestException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String every = request == null || request.every() == null ? "" : request.every().trim();
        String day = request == null || request.day() == null ? "" : request.day().trim();
        BigDecimal value = ClaimInput.signedAmount(amount);
        if (value.signum() <= 0) {
            throw new BadRequestException("amount must be more than 0");
        }
        LocalDate start = date(request == null ? null : request.start(), "start date");
        LocalDate end = date(request == null ? null : request.end(), "end date");
        Integer everyDays = null;
        Integer dayOfMonth = null;
        if (!day.isEmpty()) {
            if (!every.isEmpty()) {
                throw new BadRequestException("give either every N days or a day of the month, not both");
            }
            if (!day.matches("[0-9]{1,2}") || Integer.parseInt(day) < 1 || Integer.parseInt(day) > 31) {
                throw new BadRequestException("day must be a whole number from 1 to 31");
            }
            dayOfMonth = Integer.parseInt(day);
        } else {
            if (!every.matches("[0-9]{1,6}") || Integer.parseInt(every) < 1) {
                throw new BadRequestException("every must be a whole number of days, at least 1");
            }
            everyDays = Integer.parseInt(every);
        }
        if (end.isBefore(start)) {
            throw new BadRequestException("end date must not be before start date");
        }
        plan.set(new PlanInput(value, start, everyDays, dayOfMonth, end));
    }

    private static LocalDate date(String value, String what) throws BadRequestException {
        String v = value == null ? "" : value.trim();
        if (v.isEmpty()) {
            throw new BadRequestException(what + " is required");
        }
        try {
            return LocalDate.parse(v);
        } catch (DateTimeParseException e) {
            throw new BadRequestException(what + " must be yyyy-mm-dd");
        }
    }
}
=== plan/GeneratePlanClaims


/** For every plan on the sheet, in the order they were added, make a DRAFT claim with the plan's amount for each
 *  plan date (the start, then every N days; or monthly on its day) up to the end and the sheet's today that has none yet, dated that day
 *  with an empty note, written as CLAIM_ADDED. Each is checked by the claim form's rules: a date the form refuses
 *  is skipped (nothing written) and tried again next time. Answers how many were made. */
public class GeneratePlanClaims {
    public void generate(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            PlanRepository plans, ClaimRepository claims, SheetRepository sheets, PeriodRepository periods,
            PersonRepository people, Audit audit, Rollup rollup, Out<GenerateResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!plans.lockSheet(id)) {
            throw new BadRequestException("no such sheet");
        }
        LocalDate today = sheets.today(id);
        int made = 0;
        for (Plan plan : plans.list(id)) {
            String name = plans.personName(id, plan.personId());
            if (name == null) {
                continue;
            }
            Set<LocalDate> done = plans.madeOn(plan.id());
            LocalDate end = LocalDate.parse(plan.end());
            LocalDate last = today != null && today.isBefore(end) ? today : end;
            BigDecimal amount = new BigDecimal(plan.amount());
            for (LocalDate on : dates(plan, last)) {
                if (done.contains(on)) {
                    continue;
                }
                try {
                    PeriodGuard.open(periods, id, claims.dueBy(id, plan.personId(), on));
                    people.claimAllowed(id, plan.personId(), on);
                } catch (BadRequestException refused) {
                    continue;
                }
                Rollup.Snapshot before = rollup.take(id);
                Claim added = claims.add(id, plan.personId(), amount, on, "", null);
                claims.log(id, added.id(), by);
                plans.made(id, plan.id(), on, added.id());
                audit.record("CLAIM_ADDED sheet=" + id + " by=" + by + " person=" + name
                        + " amount=" + added.amount() + " date=" + added.date());
                if (added.lateEntry()) {
                    audit.record("LATE_ENTRY sheet=" + id + " by=" + by + " person=" + name
                            + " amount=" + added.amount() + " date=" + added.date());
                }
                rollup.record(id, by, before);
                made++;
            }
        }
        result.set(new GenerateResult(made));
    }

    /** A plan's dates up to last, in order: the start then every N days, or (monthly) that day in every month
     *  from the start's month, falling on the month's last day when beyond it, those before the start left out. */
    private static List<LocalDate> dates(Plan plan, LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        LocalDate start = LocalDate.parse(plan.start());
        if (plan.day() == null) {
            for (LocalDate on = start; !on.isAfter(last); on = on.plusDays(plan.every())) {
                dates.add(on);
            }
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate on = month.atDay(Math.min(plan.day(), month.lengthOfMonth()));
            if (!on.isBefore(start) && !on.isAfter(last)) {
                dates.add(on);
            }
        }
        return dates;
    }
}
