403	/** For every plan on the sheet, in the order they were added, make a DRAFT claim with the plan's amount for each
404	 *  plan date (the start, then every N days; or monthly on its day) up to the end and the sheet's today that has none yet, dated that day
405	 *  with an empty note, written as CLAIM_ADDED. Each is checked by the claim form's rules: a date the form refuses
406	 *  is skipped (nothing written) and tried again next time. Answers how many were made. */
407	public class GeneratePlanClaims {
408	    public void generate(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
409	            PlanRepository plans, ClaimRepository claims, SheetRepository sheets, PeriodRepository periods,
410	            PersonRepository people, Audit audit, Rollup rollup, Out<GenerateResult> result) throws BadRequestException {
411	        String by = CurrentUser.require(connection);
412	        String id = sheetId == null ? "" : sheetId.trim();
413	        if (!plans.lockSheet(id)) {
414	            throw new BadRequestException("no such sheet");
415	        }
416	        LocalDate today = sheets.today(id);
417	        int made = 0;
418	        for (Plan plan : plans.list(id)) {
419	            String name = plans.personName(id, plan.personId());
420	            if (name == null) {
421	                continue;
422	            }
423	            Set<LocalDate> done = plans.madeOn(plan.id());
424	            LocalDate end = LocalDate.parse(plan.end());
425	            LocalDate last = today != null && today.isBefore(end) ? today : end;
426	            BigDecimal amount = new BigDecimal(plan.amount());
427	            for (LocalDate on : dates(plan, last)) {
428	                if (done.contains(on)) {
429	                    continue;
430	                }
431	                try {
432	                    PeriodGuard.open(periods, id, claims.dueBy(id, plan.personId(), on));
433	                    people.claimAllowed(id, plan.personId(), on);
434	                } catch (BadRequestException refused) {
435	                    continue;
436	                }
437	                Rollup.Snapshot before = rollup.take(id);
438	                Claim added = claims.add(id, plan.personId(), amount, on, "", null);
439	                claims.log(id, added.id(), by);
440	                plans.made(id, plan.id(), on, added.id());
441	                audit.record("CLAIM_ADDED sheet=" + id + " by=" + by + " person=" + name
442	                        + " amount=" + added.amount() + " date=" + added.date());
443	                if (added.lateEntry()) {
444	                    audit.record("LATE_ENTRY sheet=" + id + " by=" + by + " person=" + name
445	                            + " amount=" + added.amount() + " date=" + added.date());
446	                }
447	                rollup.record(id, by, before);
448	                made++;
449	            }
450	        }
451	        result.set(new GenerateResult(made));
452	    }
453	
454	    /** A plan's dates up to last, in order: the start then every N days, or (monthly) that day in every month
455	     *  from the start's month, falling on the month's last day when beyond it, those before the start left out. */
456	    private static List<LocalDate> dates(Plan plan, LocalDate last) {
457	        List<LocalDate> dates = new ArrayList<>();
458	        LocalDate start = LocalDate.parse(plan.start());
459	        if (plan.day() == null) {
460	            for (LocalDate on = start; !on.isAfter(last); on = on.plusDays(plan.every())) {
461	                dates.add(on);
462	            }
463	            return dates;
464	        }
465	        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
466	            LocalDate on = month.atDay(Math.min(plan.day(), month.lengthOfMonth()));
467	            if (!on.isBefore(start) && !on.isAfter(last)) {
468	                dates.add(on);
469	            }
470	        }
471	        return dates;
472	    }
473	}
